export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

/* Registered so the gradient's radius can animate. */
@property --toast-dot {
  syntax: "<length>";
  inherits: false;
  initial-value: 2.5px;
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .region {
    position: fixed;
    z-index: 50;
    bottom: max(var(--ui-space-4), env(safe-area-inset-bottom));
    width: min(360px, 100vw - 2 * var(--ui-space-4));
    outline: none;
    font-family: var(--ui-font-sans);
  }

  .region[data-position="bottom-right"] {
    right: max(var(--ui-space-4), env(safe-area-inset-right));
  }

  .region[data-position="bottom-left"] {
    left: max(var(--ui-space-4), env(safe-area-inset-left));
  }

  .item {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    --toast-inset: var(--ui-space-4);
    --toast-close: 24px;
    --toast-radius: calc(var(--toast-inset) + var(--toast-close) / 2);
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    outline: none;
    transform-origin: 50% 100%;
    translate: 0 var(--toast-y, 0);
    scale: var(--toast-scale, 1);
    transition:
      translate var(--ui-dur-move) var(--ui-ease-move),
      scale var(--ui-dur-move) var(--ui-ease-move),
      opacity var(--ui-dur-fast) var(--ui-ease-color);
  }

  /* Leaving: it fades where it was while the rest move up. */
  .item[data-ending-style] {
    transition: opacity var(--ui-dur-fast) var(--ui-ease-exit);
  }

  /* Bridges the gap between expanded toasts so the pointer never "leaves". */
  .item::before {
    content: "";
    position: absolute;
    right: 0;
    bottom: 100%;
    left: 0;
    height: var(--ui-space-2);
  }

  .card {
    position: relative;
    border-radius: var(--toast-radius);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-floating);
    color: var(--ui-foreground);
    clip-path: var(--toast-clip, none);
    touch-action: pan-y;
    user-select: none;
    cursor: default;
    /* Base UI sets the swipe offset; released short of dismissing, it snaps back. */
    translate: var(--toast-swipe-movement-x, 0px) 0;
    transition:
      clip-path var(--ui-dur-move) var(--ui-ease-move),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
    animation: toast-in var(--ui-dur-base) var(--ui-ease-enter);
  }

  .item[data-swiping] .card {
    transition: clip-path var(--ui-dur-move) var(--ui-ease-move);
  }

  .item[data-ending-style] .card {
    transform: translateY(4px);
    transition: transform var(--ui-dur-fast) var(--ui-ease-exit);
  }

  /* Swiped away: carries on off the side at the finger's pace. */
  .item[data-ending-style][data-swipe-direction] .card {
    transform: none;
    transition: translate var(--ui-dur-fast) linear;
  }

  .item[data-ending-style][data-swipe-direction="right"] .card {
    translate: calc(100% + 32px) 0;
  }

  .item[data-ending-style][data-swipe-direction="left"] .card {
    translate: calc(-100% - 32px) 0;
  }

  .item:focus-visible .card {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .content {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-3);
    min-height: 56px;
    padding: var(--ui-space-3) var(--toast-inset) var(--ui-space-3)
      calc(var(--toast-inset) + (var(--toast-close) - 16px) / 2);
    opacity: var(--toast-content, 1);
    transition: opacity var(--ui-dur-fast) var(--ui-ease-color);
  }

  .icon {
    display: grid;
    place-items: center;
    flex-shrink: 0;
    width: var(--ui-icon-md);
    height: var(--ui-control-sm);
    color: var(--ui-foreground);
  }

  .icon svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    stroke-width: var(--ui-icon-stroke);
  }

  /* Relies on pathLength={1} on the path, which makes the dash math length-free. */
  .tick {
    stroke-dasharray: 1 2;
    animation: toast-tick var(--ui-dur-base) var(--ui-ease-draw) 120ms backwards;
  }

  @keyframes toast-tick {
    from {
      stroke-dashoffset: 1.05;
    }
    to {
      stroke-dashoffset: 0;
    }
  }

  .item[data-type="error"] .icon {
    color: var(--ui-danger-text);
  }

  .item[data-type="default"] .icon {
    color: var(--ui-muted);
  }

  .text {
    display: grid;
    flex: 1;
    gap: 2px;
    min-width: 0;
    padding-block: calc((var(--ui-control-sm) - var(--ui-leading-md)) / 2);
  }

  .title {
    margin: 0;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .description {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .action {
    flex-shrink: 0;
  }

  .close {
    position: relative;
    display: grid;
    place-items: center;
    flex-shrink: 0;
    width: var(--toast-close);
    height: var(--toast-close);
    margin: calc(var(--toast-inset) - var(--ui-space-3)) 0 0 calc(var(--ui-space-1) * -1);
    padding: 0;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-subtle);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .close::after {
    content: "";
    position: absolute;
    inset: -8px;
  }

  .close svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    pointer-events: none;
  }

  @media (hover: hover) {
    .close:hover {
      background: var(--ui-fill);
      color: var(--ui-foreground);
    }
  }

  .close:active {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  .close:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .pulse {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    background:
      radial-gradient(circle closest-side, currentColor calc(var(--toast-dot) - 0.5px), transparent var(--toast-dot)),
      radial-gradient(
        circle closest-side,
        transparent 4.3px,
        currentColor 4.6px 5.9px,
        transparent 6.2px
      );
    animation: toast-breathe var(--ui-dur-pulse) var(--ui-ease-pulse) infinite alternate;
  }

  @keyframes toast-breathe {
    from {
      --toast-dot: 1.75px;
    }
    to {
      --toast-dot: 3.5px;
    }
  }

  @keyframes toast-in {
    from {
      opacity: 0;
      transform: translateY(4px);
      filter: blur(2px);
    }
  }

  @keyframes toast-fade {
    from {
      opacity: 0;
    }
  }

  @keyframes toast-dim {
    to {
      opacity: 0.45;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .item {
      transition: opacity var(--ui-dur-fast) var(--ui-ease-color);
    }
    .item[data-ending-style] .card,
    .item[data-ending-style][data-swipe-direction] .card {
      transform: none;
      translate: none;
    }
    .card {
      transition: none;
      animation-name: toast-fade;
      animation-duration: var(--ui-dur-fast);
    }
    .tick {
      animation: none;
    }
    .pulse {
      --toast-dot: 2.75px;
      animation: toast-dim calc(var(--ui-dur-pulse) * 3) var(--ui-ease-pulse) infinite alternate;
    }
  }
}

"use client";

import { useState, type CSSProperties, type ReactNode } from "react";
import { Toast as BaseToast } from "@base-ui/react/toast";
import { Button } from "../button/button";
import { Icon } from "../icons/icons";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./toast.module.css";

/* ---------- Store ---------- */

export type ToastType = "default" | "success" | "error" | "loading";

export type ToastAction = { label: string; onClick: () => void };

export type ToastOptions = {
  id?: string;
  description?: ReactNode;
  action?: ToastAction;
  /** Milliseconds on screen; Infinity keeps it until dismissed. */
  duration?: number;
};

type ToastData = { action?: ToastAction; morph: boolean };

/** One manager for the whole app, so `toast()` works from anywhere, outside React too. */
const manager = BaseToast.createToastManager();
let counter = 0;
// Ids whose title morphs on change (toast.promise, toast.loading); sticky across updates.
const morphing = new Set<string>();

function defaultDuration(type: ToastType, action?: ToastAction) {
  if (type === "loading") return Infinity;
  if (action) return 8000;
  return type === "error" ? 6000 : 5000;
}

function upsert(type: ToastType, title: string, options: ToastOptions = {}, morph = false) {
  const id = options.id ?? `toast-${++counter}`;
  if (morph) morphing.add(id);
  const duration = options.duration ?? defaultDuration(type, options.action);
  // Adding with an id that's already shown updates it in place and restarts its timer.
  manager.add<ToastData>({
    id,
    type,
    title,
    description: options.description,
    timeout: Number.isFinite(duration) ? duration : 0,
    priority: type === "error" ? "high" : "low",
    data: { action: options.action, morph: morphing.has(id) },
    onRemove: () => morphing.delete(id),
  });
  return id;
}

function dismiss(id?: string) {
  manager.close(id);
}

type PromiseMessages<T> = {
  loading: string;
  success: string | ((value: T) => string);
  error: string | ((reason: unknown) => string);
  /** Extra options for the settled toast. */
  successOptions?: ToastOptions;
  errorOptions?: ToastOptions;
  description?: ReactNode;
};

/** Show a toast and return its id; pass it as `id` to update the toast in place. */
export const toast = Object.assign(
  (title: string, options?: ToastOptions) => upsert("default", title, options),
  {
    success: (title: string, options?: ToastOptions) => upsert("success", title, options),
    error: (title: string, options?: ToastOptions) => upsert("error", title, options),
    loading: (title: string, options?: ToastOptions) => upsert("loading", title, options, true),
    dismiss,
    /** One toast that follows a promise from loading to success or error. */
    promise<T>(promise: Promise<T>, messages: PromiseMessages<T>, options: ToastOptions = {}) {
      const id = upsert("loading", messages.loading, { ...options, description: messages.description }, true);
      promise.then(
        (value) => {
          const title = typeof messages.success === "function" ? messages.success(value) : messages.success;
          upsert("success", title, { ...options, description: messages.description, ...messages.successOptions, id });
        },
        (reason) => {
          const title = typeof messages.error === "function" ? messages.error(reason) : messages.error;
          upsert("error", title, { ...options, description: messages.description, ...messages.errorOptions, id });
        },
      );
      return promise;
    },
  },
);

/* ---------- Layout ---------- */

const GAP = 8; // matches --ui-space-2
const PEEK = 12; // how far each collapsed toast peeks out
const SHRINK = 0.03; // scale step per collapsed toast

type Vars = CSSProperties & Record<string, string | number>;
type Place = { collapsed: Vars; expanded: Vars };
type Item = BaseToast.Root.ToastObject<ToastData>;

/** Where each live toast sits, collapsed and fanned out, plus the stack's height in both. */
function stack(toasts: Item[], max: number) {
  const live = toasts.filter((t) => t.transitionStatus !== "ending");
  const frontHeight = live[0]?.height ?? 0;
  const places: Record<string, Place> = {};
  let offset = 0;
  live.forEach((t, index) => {
    const h = t.height ?? frontHeight;
    const shared = { opacity: index < max ? 1 : 0, zIndex: live.length - index };
    const clipTop = index > 0 && h > frontHeight ? h - frontHeight : -1;
    places[t.id] = {
      collapsed: {
        ...shared,
        "--toast-y": `${-index * PEEK - Math.max(0, frontHeight - h)}px`,
        "--toast-scale": 1 - index * SHRINK,
        // Unclipped, the inset reaches past the card so its shadow isn't cut off.
        "--toast-clip":
          clipTop >= 0 ? `inset(${clipTop}px 0 0 0 round var(--toast-radius))` : "inset(-40px -40px -64px -40px round 0)",
        "--toast-content": index === 0 ? 1 : 0,
      },
      expanded: {
        ...shared,
        "--toast-y": `${-offset}px`,
        "--toast-scale": 1,
        "--toast-clip": "inset(-40px -40px -64px -40px round 0)",
        "--toast-content": 1,
      },
    };
    offset += h + GAP;
  });
  // Sized to the stack, so moving onto an older toast isn't a leave.
  const shown = live.slice(0, max);
  const height = {
    collapsed: frontHeight + Math.max(0, shown.length - 1) * PEEK,
    expanded: shown.reduce((sum, t) => sum + (t.height ?? 0) + GAP, 0),
  };
  return { places, height };
}

/* ---------- Toaster ---------- */

export type ToasterProps = {
  position?: "bottom-right" | "bottom-left";
  /** How many toasts show at once. */
  max?: number;
  /** Name of the region, read with its F6 shortcut. */
  label?: string;
};

/** Renders the toasts. Built on Base UI's Toast: it owns timers, F6, swipe and announcements. */
export function Toaster({ position = "bottom-right", max = 3, label = "Notifications" }: ToasterProps) {
  // A marker in place, so the portaled stack inherits the nearest themed subtree's tokens.
  const [host, setHost] = useState<HTMLSpanElement | null>(null);
  const themed = host?.closest<HTMLElement>("[data-theme]");
  const container = themed && themed !== document.documentElement ? themed : undefined;

  return (
    <BaseToast.Provider toastManager={manager} limit={max}>
      <span ref={setHost} hidden />
      <BaseToast.Portal container={container}>
        <Stack position={position} max={max} label={label} />
      </BaseToast.Portal>
    </BaseToast.Provider>
  );
}

function Stack({ position, max, label }: Required<ToasterProps>) {
  const { toasts } = BaseToast.useToastManager<ToastData>();
  const { places, height } = stack(toasts, max);

  return (
    <BaseToast.Viewport
      className={styles.region}
      data-position={position}
      aria-label={`${label} (F6)`}
      style={(state) => ({ height: state.expanded ? height.expanded : height.collapsed })}
    >
      {toasts.map((t) => (
        <ToastItem key={t.id} toast={t} place={places[t.id]} />
      ))}
    </BaseToast.Viewport>
  );
}

/* ---------- One toast ---------- */

function ToastItem({ toast: item, place }: { toast: Item; place?: Place }) {
  const { id, title, description, data } = item;
  const type = (item.type ?? "default") as ToastType;
  const closing = item.transitionStatus === "ending";

  // A leaving toast keeps its last position while the rest move up.
  const key = JSON.stringify(place ?? null);
  const [kept, setKept] = useState({ key, place });
  if (!closing && place && kept.key !== key) setKept({ key, place });
  const applied = closing ? kept.place : place;

  return (
    <BaseToast.Root
      toast={item}
      swipeDirection={["left", "right"]}
      className={styles.item}
      style={(state) => {
        const vars = state.expanded ? applied?.expanded : applied?.collapsed;
        // The fade lives on the root: Base UI waits for the root's own transitions before removing it.
        return state.transitionStatus === "ending" ? { ...vars, opacity: 0 } : vars;
      }}
    >
      <div className={styles.card}>
        <div className={styles.content}>
          <span className={styles.icon} aria-hidden="true">
            <ToastIcon type={type} />
          </span>
          <div className={styles.text}>
            <BaseToast.Title className={styles.title} render={<p />}>
              {data?.morph ? <TextMorph>{String(title ?? "")}</TextMorph> : title}
            </BaseToast.Title>
            {description && <BaseToast.Description className={styles.description}>{description}</BaseToast.Description>}
          </div>
          {data?.action && (
            <Button
              variant="secondary"
              className={styles.action}
              onClick={() => {
                data.action!.onClick();
                dismiss(id);
              }}
            >
              {data.action.label}
            </Button>
          )}
          <BaseToast.Close className={styles.close} aria-label={`Dismiss: ${String(title ?? "")}`}>
            <Icon name="close" />
          </BaseToast.Close>
        </div>
      </div>
    </BaseToast.Root>
  );
}

function ToastIcon({ type }: { type: ToastType }) {
  if (type === "loading") return <span className={styles.pulse} />;
  if (type === "success")
    return (
      <svg viewBox="0 0 16 16">
        <circle cx="8" cy="8" r="6.25" fill="none" stroke="currentColor" />
        <path className={styles.tick} d="M5.4 8.2l1.8 1.8 3.4-3.6" pathLength={1} fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  if (type === "error")
    return (
      <svg viewBox="0 0 16 16">
        <circle cx="8" cy="8" r="6.25" fill="none" stroke="currentColor" />
        <path d="M8 4.75v3.75" stroke="currentColor" strokeLinecap="round" />
        <circle cx="8" cy="11" r="0.9" fill="currentColor" />
      </svg>
    );
  return (
    <svg viewBox="0 0 16 16">
      <circle cx="8" cy="8" r="6.25" fill="none" stroke="currentColor" />
      <path d="M8 7.5v3.5" stroke="currentColor" strokeLinecap="round" />
      <circle cx="8" cy="5" r="0.9" fill="currentColor" />
    </svg>
  );
}
